	deliveryDone := make(chan struct{})
	go func() {
		defer close(deliveryDone)
		h.runDeliveries(ctx)
	}()
	defer func() {
		close(h.deliveries)
		<-deliveryDone
	}()

	for {
		select {
		case <-ctx.Done():
			return
		case c := <-h.reg:
			h.mu.Lock()
			h.clients[c] = struct{}{}
			set := h.byUser[c.UserID]
			firstForUser := false
			if set == nil {
				set = map[*Client]struct{}{}
				h.byUser[c.UserID] = set
				firstForUser = true
			}
			set[c] = struct{}{}
			cb := h.OnConnect
			h.mu.Unlock()
			if firstForUser && cb != nil {
				go cb(c.UserID)
			}
		case c := <-h.unreg:
			h.mu.Lock()
			delete(h.clients, c)
			lastForUser := false
			if set := h.byUser[c.UserID]; set != nil {
				delete(set, c)
				if len(set) == 0 {
					delete(h.byUser, c.UserID)
					lastForUser = true
				}
			}
			close(c.Send)
			cb := h.OnDisconnect
			h.mu.Unlock()
			if lastForUser && cb != nil {
				go cb(c.UserID)
			}
