// Request bodies that carry a client-supplied collection — a bulk id array, a
// batch of memberships, a props map — cost the server the most per byte.
// json.Decode materializes the whole collection before any handler-side length
// check runs, so the `if len(ids) > 200 { ids = ids[:200] }` guards scattered
// through the compat handlers bound what we *query*, not what we *buffer*: the
// array is already on the heap by the time they run. Several of these handlers
// then spend one database round-trip per element. Left unbounded, a single
// authenticated request can pin arbitrary heap and issue arbitrarily many
// queries, so every collection-shaped body reads through decodeCollectionBody.
//
// collectionBodyMaxBytes is deliberately generous — the largest legitimate
// body in this group is a post with rich props, and Mattermost's own default
// payload ceiling is roughly 300 KB.
const collectionBodyMaxBytes = 1 << 20

// maxBulkItems bounds the element count of a batch that writes once per
// element. Read-side bulk lookups keep Mattermost's silent truncation to 200
// so an over-long lookup still answers; silently dropping half of a *write*
// would be worse than refusing it, so the write batches reject instead.
const maxBulkItems = 200

// decodeCollectionBody decodes an array- or map-shaped request body under
// collectionBodyMaxBytes. On failure it has already answered the request —
// 413 when the body outgrew the cap, 400 when it was malformed — and returns
// false, so call sites read `if !decodeCollectionBody(...) { return }`. errID
// is the Mattermost-style error id the handler already used for a bad body;
// the status code, not the id, is what tells the two failures apart.
func decodeCollectionBody(w http.ResponseWriter, r *http.Request, errID string, dst any) bool {
	if err := decodeCappedBody(w, r, dst); err != nil {
		var tooLarge *http.MaxBytesError
		if errors.As(err, &tooLarge) {
			writeError(w, http.StatusRequestEntityTooLarge, errID,
				fmt.Sprintf("request body exceeds %d bytes", collectionBodyMaxBytes))
			return false
		}
		writeError(w, http.StatusBadRequest, errID, err.Error())
		return false
	}
	return true
}

// decodeOptionalCollectionBody is decodeCollectionBody for a write batch whose
// body is optional. json.Decode answers io.EOF for an absent body, and a
// bulk endpoint that has always treated "no body" as "an empty batch" keeps
// doing so — nothing documents that tolerance, but no caller was found to
// depend on it either, so it is preserved conservatively rather than turned
// into a 400 by this change. Every *other* decode failure is refused exactly as
// decodeCollectionBody refuses it, because the alternative is reporting a
// write that never happened: a body over the cap or truncated mid-array
// leaves the destination zeroed, and answering 200 "count: 0" tells the
// sender the batch was processed and stops it retrying.
func decodeOptionalCollectionBody(w http.ResponseWriter, r *http.Request, errID string, dst any) bool {
	err := decodeCappedBody(w, r, dst)
	if err == nil || errors.Is(err, io.EOF) {
		return true
	}
	var tooLarge *http.MaxBytesError
	if errors.As(err, &tooLarge) {
		writeError(w, http.StatusRequestEntityTooLarge, errID,
			fmt.Sprintf("request body exceeds %d bytes", collectionBodyMaxBytes))
		return false
	}
	writeError(w, http.StatusBadRequest, errID, err.Error())
	return false
}

// decodeCappedBody is decodeCollectionBody without the response. A handful of
// compat stubs deliberately tolerate a malformed body (they decode with
// `_ =` and treat the result as empty); they still need the read capped, but
// turning their 200 into a 400 would be a behavior change unrelated to the
// resource bound.
func decodeCappedBody(w http.ResponseWriter, r *http.Request, dst any) error {
	return json.NewDecoder(http.MaxBytesReader(w, r.Body, collectionBodyMaxBytes)).Decode(dst)
}

// drainCappedBody reads and discards a request body under limit bytes and
// reports how many bytes it consumed and whether the body fit. The multipart
// upload stubs don't persist anything yet, so draining is all they do with the
// bytes — but a drain that stopped because MaxBytesReader refused to hand over
// byte limit+1 has not received the upload, and neither has one that died
// mid-read. Answering 200 there tells the client its file landed, leaves an
// audit row for an upload that never happened, and — for the chunk endpoint —
// hands back the truncated count as the offset a resuming client continues
// from. So call sites read `if n, ok := drainCappedBody(...); !ok { return }`
// and must return before their audit call.
//
// errID stays with the caller because each endpoint documents its own
// Mattermost-style id; as in decodeCollectionBody it is the status code, not
// the id, that separates "too large" from "malformed".
func drainCappedBody(w http.ResponseWriter, r *http.Request, limit int64, errID string) (int64, bool) {
	n, err := io.Copy(io.Discard, http.MaxBytesReader(w, r.Body, limit))
	if err == nil {
		return n, true
	}
	var tooLarge *http.MaxBytesError
	if errors.As(err, &tooLarge) {
		writeError(w, http.StatusRequestEntityTooLarge, errID,
			fmt.Sprintf("request body exceeds %d bytes", limit))
		return n, false
	}
// (signals: the post appears in one of their channels AND that channel's
// mention_count is currently nonzero). The detail SQL approximates what
// the client sees in its sidebar badges.
func (w *Worker) loadMentions(ctx context.Context, userID string) ([]email.DigestMention, error) {
	rows, err := w.db.Pool.Query(ctx, `
		SELECT u.username, c.display_name, p.message, p.create_at
		FROM channel_members cm
		JOIN channels c ON c.id = cm.channel_id AND c.delete_at = 0
		JOIN posts p ON p.channel_id = cm.channel_id
		JOIN users u ON u.id = p.user_id
		WHERE cm.user_id = $1
		  AND cm.mention_count > 0
		  AND p.delete_at = 0
		  AND p.create_at > (SELECT COALESCE(cm2.last_viewed_at, 0)
		                    FROM channel_members cm2
		                    WHERE cm2.user_id = $1 AND cm2.channel_id = c.id)
		ORDER BY p.create_at DESC
		LIMIT 20
	`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []email.DigestMention{}
	for rows.Next() {
		var uname, ch, msg string
		var postedAt int64
		if err := rows.Scan(&uname, &ch, &msg, &postedAt); err != nil {
			return nil, err
		}
		out = append(out, email.DigestMention{
			Username:    uname,
			ChannelName: ch,
			Excerpt:     truncateRunes(msg, 160),
			PostedAt:    time.UnixMilli(postedAt).Local().Format("1/2 15:04"),
		})
	}
	return out, rows.Err()
}

// truncateRunes shortens a mention excerpt to at most limit characters. The
// cut counts runes rather than bytes because the digest templates are Korean
// and one Hangul syllable is three UTF-8 bytes: a byte cut lands inside a
// character far more often than not, and the excerpt that reaches the
// recipient is then not valid UTF-8 — mail clients render it as a replacement
// glyph. ASCII excerpts are unaffected, since there a rune is a byte. Mirrors
// the rune-counting cut knowledge.truncateRunes already uses.
func truncateRunes(value string, limit int) string {
	if utf8.RuneCountInString(value) <= limit {
		return value
	}
	return string([]rune(value)[:limit]) + "…"
}

